CREATE TABLE organizations (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE branches (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, name text NOT NULL, UNIQUE(organization_id,id));
CREATE TABLE members (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, branch_id text, display_name text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(organization_id,id), FOREIGN KEY(organization_id,branch_id) REFERENCES branches(organization_id,id));
CREATE TABLE grants (member_id text NOT NULL REFERENCES members, permission text NOT NULL, branch_id text REFERENCES branches, PRIMARY KEY(member_id,permission));
CREATE TABLE fixture_sessions (digest text PRIMARY KEY, member_id text NOT NULL REFERENCES members, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE programs (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, title text NOT NULL, local_date date NOT NULL, state text NOT NULL DEFAULT 'SCHEDULED' CHECK(state IN ('SCHEDULED','LIVE_CONFIRMED','SUSPECTED_INTERRUPTION','RECOVERY_SEARCH','AWAITING_ADMIN','COMPLETED')), revision integer NOT NULL DEFAULT 0, current_sequence integer, UNIQUE(organization_id,id));
CREATE TABLE official_channels (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, program_id text NOT NULL, approved boolean NOT NULL DEFAULT false, mock boolean NOT NULL DEFAULT true, FOREIGN KEY(organization_id,program_id) REFERENCES programs(organization_id,id));
CREATE TABLE stream_versions (program_id text NOT NULL REFERENCES programs, sequence integer NOT NULL, video_id text NOT NULL CHECK(video_id ~ '^[A-Za-z0-9_-]{11}$'), channel_id text NOT NULL REFERENCES official_channels, observed_at timestamptz NOT NULL, reason text NOT NULL, PRIMARY KEY(program_id,sequence));
ALTER TABLE programs ADD CONSTRAINT current_stream_fk FOREIGN KEY(id,current_sequence) REFERENCES stream_versions(program_id,sequence);
CREATE TABLE mock_observations (id bigserial PRIMARY KEY, program_id text NOT NULL REFERENCES programs, video_id text NOT NULL, channel_id text NOT NULL, title text NOT NULL, live boolean NOT NULL, available boolean NOT NULL DEFAULT true, provider_error boolean NOT NULL DEFAULT false, observed_at timestamptz NOT NULL DEFAULT now(), expected_revision integer NOT NULL, processed boolean NOT NULL DEFAULT false, outcome text);
CREATE TABLE domain_outbox (id bigserial PRIMARY KEY, event_key text NOT NULL UNIQUE, program_id text NOT NULL REFERENCES programs, event_type text NOT NULL, revision integer NOT NULL, processed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE preferences (member_id text PRIMARY KEY REFERENCES members, live_start boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 0);
CREATE TABLE consent_records (id bigserial PRIMARY KEY, member_id text NOT NULL REFERENCES members, purpose text NOT NULL, opted_in boolean NOT NULL, wording_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE join_links (digest text PRIMARY KEY, organization_id text NOT NULL, member_id text NOT NULL, program_id text NOT NULL, purpose text NOT NULL CHECK(purpose IN ('LIVE_LINK_OPENED','REPLAY_LINK_OPENED')), expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id), FOREIGN KEY(organization_id,program_id) REFERENCES programs(organization_id,id));
CREATE TABLE join_nonces (digest text PRIMARY KEY, token_digest text NOT NULL REFERENCES join_links, browser_digest text NOT NULL, expires_at timestamptz NOT NULL, consumed boolean NOT NULL DEFAULT false);
CREATE TABLE checkin_events (organization_id text NOT NULL, member_id text NOT NULL, program_id text NOT NULL, action text NOT NULL CHECK(action IN ('LIVE_LINK_OPENED','REPLAY_LINK_OPENED')), first_opened_at timestamptz NOT NULL DEFAULT now(), last_opened_at timestamptz NOT NULL DEFAULT now(), assurance text NOT NULL CHECK(assurance IN ('TOKEN_ASSOCIATED','AUTHENTICATED_MEMBER')), stream_sequence integer NOT NULL, PRIMARY KEY(organization_id,member_id,program_id,action), FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id), FOREIGN KEY(organization_id,program_id) REFERENCES programs(organization_id,id), FOREIGN KEY(program_id,stream_sequence) REFERENCES stream_versions(program_id,sequence));
CREATE TABLE budgets (organization_id text PRIMARY KEY REFERENCES organizations, currency text NOT NULL DEFAULT 'TEST', cap_units bigint NOT NULL CHECK(cap_units >= 0), reserved_units bigint NOT NULL DEFAULT 0 CHECK(reserved_units >= 0 AND reserved_units <= cap_units));
CREATE TABLE notifications (id bigserial PRIMARY KEY, organization_id text NOT NULL, program_id text NOT NULL, member_id text NOT NULL, purpose text NOT NULL DEFAULT 'LIVE_START', channel text NOT NULL DEFAULT 'MOCK_WHATSAPP', message_version integer NOT NULL DEFAULT 1, state text NOT NULL DEFAULT 'PLANNED', reason text, payload_cipher text, expires_at timestamptz NOT NULL, cost_units bigint NOT NULL DEFAULT 1 CHECK(cost_units > 0), UNIQUE(organization_id,program_id,member_id,purpose,channel,message_version), FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id), FOREIGN KEY(organization_id,program_id) REFERENCES programs(organization_id,id));
CREATE TABLE cost_ledger (id bigserial PRIMARY KEY, notification_id bigint NOT NULL UNIQUE REFERENCES notifications, units bigint NOT NULL, currency text NOT NULL DEFAULT 'TEST', kind text NOT NULL DEFAULT 'SIMULATED_RESERVATION');
CREATE TABLE webhook_inbox (event_key text PRIMARY KEY, payload jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed boolean NOT NULL DEFAULT false);
CREATE TABLE worker_heartbeats (id text PRIMARY KEY, seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, resource_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX member_history_idx ON checkin_events(member_id,first_opened_at DESC);
CREATE INDEX pending_observations_idx ON mock_observations(id) WHERE NOT processed;
CREATE INDEX pending_outbox_idx ON domain_outbox(id) WHERE NOT processed;
CREATE INDEX notification_pending_idx ON notifications(state,expires_at);
